class Solution {
  private static final long MOD = 1_000_000_007L;

  public int makeStringSorted(String s) {
    int n = s.length();
    long[] fact = new long[n + 1], invDen = new long[1];
    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
    int[] freq = new int[26];
    for (int i = 0; i < n; i++) freq[s.charAt(i) - 'a']++;
    long denominator = 1;
    for (int f : freq) denominator = denominator * fact[f] % MOD;
    invDen[0] = pow(denominator, MOD - 2);
    Fenwick bit = new Fenwick(26);
    for (int i = 0; i < 26; i++) bit.add(i, freq[i]);
    long rank = 1;
    int remaining = n;
    for (int i = 0; i < n; i++) {
      int c = s.charAt(i) - 'a', smaller = bit.sum(c - 1);
      rank = (rank + smaller * fact[remaining - 1] % MOD * invDen[0]) % MOD;
      int old = freq[c]--;
      invDen[0] = invDen[0] * old % MOD;
      bit.add(c, -1);
      remaining--;
    }
    return (int) ((rank - 1 + MOD) % MOD);
  }

  private long pow(long a, long e) {
    long r = 1;
    while (e > 0) {
      if ((e & 1) == 1) r = r * a % MOD;
      a = a * a % MOD;
      e >>= 1;
    }
    return r;
  }

  private static class Fenwick {
    int[] t;

    Fenwick(int n) {
      t = new int[n + 1];
    }

    void add(int i, int v) {
      for (i++; i < t.length; i += i & -i) t[i] += v;
    }

    int sum(int i) {
      int r = 0;
      for (i++; i > 0; i -= i & -i) r += t[i];
      return r;
    }
  }
}
